// import React, { Component } from "react";
import queryString from 'query-string';
import EventEmitter from './libs/EventEmitter';
import translate from './libs/translations';
import ReactMustache from 'react-mustache';
import settingsGetter from './libs/settingsGetter';
import FormMain from './libs/FormMain';
import Mustache from 'mustache';
import { Parser } from 'html-to-react';

const htmlToReactParser = new Parser();

class Results extends Component {
  constructor() {
    let params = queryString.parse(window.location.search);
    super();
    const structuredSearchProps = window.mw?.config.get('structuredSearchProps') || {};

    this.state = {
      searchStarted: params.advanced_search ? true : false,
      searchReturned: false,
      hasResultsSumHidden: structuredSearchProps.resultsSumMessage === "hidden",
      resultClass: structuredSearchProps.class || "",
      displayTemplate: structuredSearchProps.display || "",
      loading: true,
      isFetching: false, // Track ongoing fetches
    };

    EventEmitter.on('searchStarted', (data) => {
      let paramsToChange = {
        searchStarted: true,
        onTop: data.reset,
        searchReturned: false,
        loading: true,
        isFetching: false, // Reset fetching state on new search
      };
      if (data.reset) {
        paramsToChange.results = [];
        paramsToChange.lastIsError = false;
        paramsToChange.total = 0;
      }
      this.setState(paramsToChange);
    });

    EventEmitter.on('dataRecieved', (data) => {
      let results = data.results;
      if (!data || !data.results) {
        console.error("Error: No results received", data);
        return;
      }

      if (results && results.error) {
        this.setState({
          lastIsError: true,
          results: [],
          searchReturned: true,
          searchStarted: false,
          onTop: false,
          loading: false,
          isFetching: false, // Reset fetch state
        });
      } else {
        let newResults = data.reset ? results : { ...this.state.results, ...results };
        let newTotal = data.searchinfo?.totalhits || 0;

        this.setState({
          offset: data.continue ? data.continue.sroffset : null,
          total: newTotal,
          lastIsError: false,
          results: newResults,
          searchReturned: true,
          searchStarted: false,
          onTop: false,
          loading: false,
          isFetching: false, // Reset fetch state after receiving results
        });
      }
    });

    settingsGetter.get().then((data) => {
      if (data) {
        this.templates = data.templates;
      }
    });

    this.handleScroll = this.handleScroll.bind(this);
  }

  componentDidMount() {
    this.retryInterval = setInterval(() => {
      this.checkStructuredSearchProps();
    }, 500);
    setTimeout(() => clearInterval(this.retryInterval), 600);

    window.addEventListener("scroll", this.handleScroll);
  }

  componentWillUnmount() {
    window.removeEventListener("scroll", this.handleScroll);
  }

  handleScroll() {
    if (this.state.isFetching || !this.state.offset) return;

    const scrollPosition = window.innerHeight + window.scrollY;
    const documentHeight = document.documentElement.scrollHeight;

    if (scrollPosition >= documentHeight - 100) {
      this.setState({ isFetching: true }, () => this.next());
    }
  }

  next() {
    if (this.state.offset) {
      FormMain.setNext(this.state.offset);
    }
  }

  render() {
    const namespace = window.mw?.config.get("wgNamespaceNumber");
    const isTemplatePage = namespace === 10;

    let results = [],
      errorHtml,
      resultsSum = "",
      searchTop = "",
      searchBottom = "";

    if (this.state.searchStarted) {
      if (this.state.onTop) {
        searchTop = (
          <div className="loading loading-top" dangerouslySetInnerHTML={{ __html: this.onSearchText }}></div>
        );
      } else {
        searchBottom = (
          <div className="loading loading-bottom" dangerouslySetInnerHTML={{ __html: this.onSearchText }}></div>
        );
      }
    }

    if (this.state.results) {
      for (let resultKey of Object.keys(this.state.results)) {
        let result = this.state.results[resultKey];
        results.push(this.getResultJsx(result));
      }

      if (this.state.searchReturned && !Object.keys(this.state.results).length) {
        if (this.state.lastIsError) {
          errorHtml = (
            <div className="no-results no-results-error" key={"error"} dangerouslySetInnerHTML={{ __html: this.noResultsError }}></div>
          );
        } else {
          errorHtml = (
            <div className="no-results no-results-empty" key={"error"} dangerouslySetInnerHTML={{ __html: this.noResults }}></div>
          );
        }
      }
    }

    if (!this.state.hasResultsSumHidden && results && this.resultsSumText && this.state.total) {
      let resultText = this.resultsSumText.replace("$1", this.state.total);
      resultsSum = <div className="results-sum-message" dangerouslySetInnerHTML={{ __html: resultText }}></div>;
    }

    return (
      <div className={`results ${this.state.resultClass}`}>
        {!isTemplatePage && this.state.loading && (
          <div className="loading-overlay">
            <div className="spinner"></div>
          </div>
        )}
        {searchTop}
        {resultsSum}
        {results}
        {errorHtml}
        {searchBottom}

        {/* Show loading spinner when fetching new results */}
        {this.state.isFetching && (
          <div className="loading loading-bottom">
            <div className="spinner"></div> Loading more results...
          </div>
        )}
      </div>
    );
  }
}

export default Results;
